/* MES-UIREF-APP-001: isolated in-memory UI prototype; no production API calls. */
(() => {
  const base = window.referenceData;
  const state = {
    workorders: structuredClone(base.workorders), assets: structuredClone(base.assets),
    categories: structuredClone(base.categories), inventory: structuredClone(base.inventory),
    purchases: structuredClone(base.purchases), contracts: structuredClone(base.contracts), financeCosts: structuredClone(base.financeCosts),
    mapSites: structuredClone(base.mapSites), mapHubs:structuredClone(base.mapHubs), mapView:'china', mapProduct:'全部产品', mapYears:'全部年限', selectedSite:'SITE-CN-001', mapUpdated:new Date(),
    people: structuredClone(base.people),
    roles: structuredClone(base.roles), devices: structuredClone(base.devices),
    qrLabels: structuredClone(base.qrLabels), qrEvents: structuredClone(base.qrEvents),
    audit: structuredClone(base.audit), view: 'front/overview', query: '', status: '',
    qrResult: null, toastTimer: null
  };
  const $ = (selector, root=document) => root.querySelector(selector);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const nav = [
    {group:'前台业务',links:[['front/overview','运营概览','⌂'],['front/production','生产工作台','▦','3']]},
    {group:'数据台账',links:[['data/assets','客户资产','▣'],['data/inventory','库存中心','▤'],['data/purchasing','采购管理','↧'],['data/commercial','报价与合同','▧'],['data/finance','财务看板','￥']]},
    {group:'后台管理',links:[['admin/people','组织与员工','♙'],['admin/roles','角色权限','▥'],['admin/audit','操作审计','◷']]},
    {group:'二维码追溯',links:[['qr/scan','扫码工作台','⌗'],['qr/devices','设备绑定','▣'],['qr/labels','标签管理','▤'],['qr/history','扫码记录','◷']]}
  ];
  const titles = Object.fromEntries(nav.flatMap(group => group.links.map(([route,title]) => [route,title])));
  const statuses = ['全部状态','入场检测','故障诊断','维修中','等待备件','待出厂检验','完成 OQC'];
  const pillClass = value => ({'入场检测':'pill-cyan','故障诊断':'pill-blue','维修中':'pill-amber','等待备件':'pill-red','待出厂检验':'pill-blue','完成 OQC':'pill-green','已绑定':'pill-green','待绑定':'pill-amber','分批到货':'pill-amber','待审批':'pill-red','已收齐':'pill-green','在岗':'pill-green','外出':'pill-gray'}[value] || 'pill-gray');
  const pill = value => `<span class="pill ${pillClass(value)}">${esc(value)}</span>`;
  const btn = (label, action, primary=false, extra='') => `<button class="btn ${primary?'btn-primary':''}" data-action="${action}" ${extra}>${label}</button>`;
  const head = (title, sub, action='') => `<div class="page-head"><div><div class="eyebrow">${esc(title==='运营概览'?'OPERATIONS CENTER':'XAIGIN · MES WORKSPACE')}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="page-actions">${action}</div></div>`;
  const panel = (title, body, trailing='') => `<section class="panel"><div class="panel-head"><h2>${esc(title)}</h2>${trailing}</div><div class="panel-body">${body}</div></section>`;
  const table = (headers, rows, empty='暂无匹配记录') => {const count=(rows.match(/<tr(?:\s|>)/g)||[]).length;return `<div class="table-card"><div class="table-scroll"><table class="data-table"><thead><tr>${headers.map(item=>`<th>${esc(item)}</th>`).join('')}</tr></thead><tbody>${rows || `<tr><td colspan="${headers.length}" class="empty-state">${esc(empty)}</td></tr>`}</tbody></table></div><div class="table-footer"><span>演示数据 · 当前 ${count} 条</span><span>仅供页面参考</span></div></div>`};
  const miniQr = () => `<span class="qr-mini" aria-label="装饰性二维码预览">${Array.from({length:25},()=>'<i></i>').join('')}</span>`;
  const money = amount => `¥ ${new Intl.NumberFormat('zh-CN',{maximumFractionDigits:0}).format(amount||0)}`;
  const field = (name, placeholder, value='') => `<input class="field" name="${esc(name)}" placeholder="${esc(placeholder)}" value="${esc(value)}">`;
  const select = (name, choices, selected='') => `<select class="field" name="${esc(name)}">${choices.map(value=>`<option ${value===selected?'selected':''}>${esc(value)}</option>`).join('')}</select>`;
  function showToast(text){const toast=$('#toast');toast.textContent=text;toast.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>toast.classList.remove('show'),2300)}
  function route(){closeDrawer();state.view=location.hash.replace(/^#\//,'')||'front/overview';if(!titles[state.view]&&!state.view.startsWith('data/inventory/'))state.view='front/overview';render()}
  function renderNav(){ $('#sideNav').innerHTML=nav.map(group=>`<div class="nav-group"><div class="nav-label">${group.group}</div>${group.links.map(([route,title,icon,badge])=>`<a class="nav-link ${state.view===route||state.view.startsWith(route+'/')?'active':''}" href="#/${route}"><span class="nav-icon">${icon}</span><span>${title}</span>${badge?`<span class="nav-badge">${badge}</span>`:''}</a>`).join('')}</div>`).join('') }
  function kpi(label,value,foot,icon,trend=''){return `<div class="kpi-card"><div class="kpi-top"><span>${label}</span><span class="kpi-icon">${icon}</span></div><div class="kpi-number">${value}</div><div class="kpi-foot"><span class="trend">${trend}</span> ${foot}</div><svg class="kpi-accent" viewBox="0 0 55 28" aria-hidden="true"><path d="M0 24 Q15 20 21 16 T39 12 T55 2" fill="none" stroke="#12a9ab" stroke-width="2"/></svg></div>`}
  function workRow(item){return `<div class="queue-row" data-work="${esc(item.id)}"><div><div class="work-title"><span class="work-id">${esc(item.id)}</span> · ${esc(item.model)}</div><div class="work-sub">${esc(item.customer)}　${esc(item.sn)}<br>${esc(item.fault)}</div></div><div>${pill(item.status)}</div><div class="owner-cell">${esc(item.owner)}</div><div class="time-cell">${esc(item.updated)}　›</div></div>`}
  function mapSvg(sites){
    const isWorld=state.mapView==='world';
    const bounds=isWorld?[-180,-60,180,85]:[73,17.5,135,54.5], width=960,height=520,pad=10;
    const merc=lat=>Math.log(Math.tan(Math.PI/4+Math.max(-85.05112878,Math.min(85.05112878,lat))*Math.PI/360));
    const [west,south,east,north]=bounds,x0=west*Math.PI/180,x1=east*Math.PI/180,y0=merc(south),y1=merc(north);
    const scale=Math.min((width-pad*2)/(x1-x0),(height-pad*2)/(y1-y0)),ox=(width-(x1-x0)*scale)/2,oy=(height-(y1-y0)*scale)/2;
    const project=(lon,lat)=>[ox+(lon*Math.PI/180-x0)*scale,height-(oy+(merc(lat)-y0)*scale)];
    const geometry=window.mapGeometry?.[isWorld?'world':'china']||[];
    const shapes=geometry.map(feature=>`<path class="country-shape ${feature.china?'china-country':''}" d="${feature.d}"/>`).join('');
    const borders=isWorld?'':geometry.map(feature=>`<path class="country-border ${feature.china?'china-boundary':''}" d="${feature.b||''}"/>`).join('');
    const dots=sites.map(site=>{const [x,y]=project(site.lon,site.lat);const klass=`map-point ${site.kind==='business'?'is-business':'is-target'} ${site.id===state.selectedSite?'is-selected':''}`;const size=4+site.years*1.25,symbolSize=5.2;const symbol=site.product==='B300系列'?`<circle class="point-symbol" cx="${x}" cy="${y}" r="${symbolSize}"/>`:site.product==='H系列'?`<path class="point-symbol" d="M${x} ${y-symbolSize} ${x+symbolSize} ${y+symbolSize*.7} ${x-symbolSize} ${y+symbolSize*.7}Z"/>`:`<rect class="point-symbol" x="${x-symbolSize*.75}" y="${y-symbolSize*.75}" width="${symbolSize*1.5}" height="${symbolSize*1.5}" rx="1"/>`;return `<g class="${klass}" role="button" tabindex="0" aria-label="${esc(site.city)} · ${site.kind==='business'?'已有合同':'目标客户'} · ${esc(site.product)} · ${site.years}年维保" data-map-site="${esc(site.id)}"><circle class="point-halo" cx="${x}" cy="${y}" r="12"/><circle class="term-ring" cx="${x}" cy="${y}" r="${size}"/><circle class="point-hit" cx="${x}" cy="${y}" r="14"/>${symbol}<text x="${x+site.labelDx}" y="${y+site.labelDy}">${esc(site.city)}</text></g>`}).join('');
    const hubs=isWorld?'':state.mapHubs.map(hub=>{const [x,y]=project(hub.lon,hub.lat);return `<g class="hub-point" role="img" aria-label="${esc(hub.name)}：${esc(hub.cluster)}，区域定位示意"><circle class="hub-area" cx="${x}" cy="${y}" r="15"/><path class="hub-diamond" d="M${x} ${y-6} ${x+6} ${y} ${x} ${y+6} ${x-6} ${y}Z"/><text class="hub-number" x="${x}" y="${y+2.8}">${hub.id.slice(-2)}</text><text class="hub-name" x="${x+hub.labelDx}" y="${y+hub.labelDy}">${esc(hub.name.replace('枢纽',''))}</text></g>`}).join('');
    return `<svg class="coverage-map ${isWorld?'world-map':'china-map'}" viewBox="0 0 ${width} ${height}" role="group" aria-label="${isWorld?'全球':'中国'}二维机房与客户点位地图"><rect class="map-water" width="${width}" height="${height}" rx="14"/><g class="country-layer" fill-rule="evenodd">${shapes}${borders}</g><g class="site-layer">${dots}</g><g class="hub-layer">${hubs}</g></svg>`;
  }
  function mapPanel(){
    const sites=state.mapSites.filter(site=>(state.mapView==='world'||site.china)&& (state.mapProduct==='全部产品'||site.product===state.mapProduct) && (state.mapYears==='全部年限'||`${site.years}年`===state.mapYears));
    const selected=sites.find(site=>site.id===state.selectedSite)||sites[0];
    const signed=sites.filter(site=>site.kind==='business').length,target=sites.filter(site=>site.kind==='target').length;
    const contract=selected?.contractId?state.contracts.find(item=>item.id===selected.contractId):null;
    return `<section class="panel coverage-panel"><div class="panel-head"><div><h2>${state.mapView==='world'?'全球机房与客户拓展':'全国机房与目标客户分布'}</h2><p>签约及在服客户、潜在线索和维修维保服务覆盖</p></div><div class="map-head-actions"><span class="map-live"><i></i>演示自动刷新 · ${esc(state.mapUpdated.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'}))}</span><button class="btn btn-sm ${state.mapView==='china'?'btn-primary':''}" data-map-view="china">中国</button><button class="btn btn-sm ${state.mapView==='world'?'btn-primary':''}" data-map-view="world">全球</button></div></div><div class="panel-body"><div class="map-toolbar"><label>产品系列 ${select('mapProduct',['全部产品','B300系列','H系列','GB系列'],state.mapProduct)}</label><label>维保年限 ${select('mapYears',['全部年限','1年','2年','3年','4年','5年'],state.mapYears)}</label><span class="map-count"><b>${signed}</b> 已签约 / 在服　<b>${target}</b> 目标客户　<b>${sites.length}</b> 个示例点位</span></div><div class="map-legend"><span><i class="legend-dot business-dot"></i>已有业务 / 合同</span><span><i class="legend-dot target-dot"></i>目标客户</span><span class="series-key"><i>●</i>B300</span><span class="series-key"><i>▲</i>H</span><span class="series-key"><i>■</i>GB</span><span class="panel-head-meta">圆环大小代表 1–5 年维保 · 点位为演示数据</span></div><div class="hub-legend"><b>八大国家算力枢纽 · 区域定位示意</b>${state.mapHubs.map(hub=>`<span><i>${hub.id.slice(-2)}</i>${esc(hub.name.replace("枢纽",""))} · ${esc(hub.cluster)}</span>`).join("")}</div><div class="map-layout"><div class="map-canvas">${mapSvg(sites)}</div><aside class="map-detail">${selected?`<span class="map-kind ${selected.kind==='business'?'kind-business':'kind-target'}">${selected.kind==='business'?'已有业务 / 已签合同':'目标客户'}</span><h3>${esc(selected.name)}</h3><p>${esc(selected.city)} · ${esc(selected.province)}</p><div class="map-facts"><span><small>服务器系列</small><b>${esc(selected.product)}</b></span><span><small>服务期限</small><b>${selected.years} 年维保</b></span></div>${contract?`<div class="map-contract"><small>关联合同 · ${esc(contract.id)}</small><b>${money(contract.amount)}</b><a href="#/data/finance">查看财务看板 →</a></div>`:`<div class="map-contract target-contract"><small>拓展方向</small><b>待建立客户关系</b><a href="#/data/commercial">查看商务台账 →</a></div>`}`:`<div class="empty-state">当前筛选没有地图点位</div>`}</aside></div><div class="map-note">底图：Natural Earth 1:50m 国家/地区边界，经纬度二维投影。橙色编号为八大国家算力枢纽的区域定位示意，圆点城市位置为示例坐标；客户、目标机房数据为虚构。演示每 30 秒仅更新时间戳，正式业务点位需接入客户/合同/服务系统。</div></div></section>`;
  }
  function overview(){
    const open=state.workorders.filter(item=>item.status!=='完成 OQC').length;
    return head('运营概览','早上好，演示账号。这里汇总维修中心当前运营与当班待办。',btn('＋ 新建工单','new-work',true))+
      `<div class="kpi-grid">${kpi('进行中工单',String(open).padStart(2,'0'),'较昨日新增 2 单','▦','↗ 12%')}${kpi('待质量检验','04','其中 1 台加急','✓','需关注')}${kpi('备件库存预警','03','低于安全库存','▤','3 个 SKU')}${kpi('今日扫码交接','128','扫码核验事件','⌗','↗ 8.4%')}</div>`+
      mapPanel()+
      panel('维修工序负载','<div class="status-rail"><div class="rail-step done">收货拆包</div><div class="rail-step current">入场检测</div><div class="rail-step">故障诊断</div><div class="rail-step">维修组装</div><div class="rail-step">维修测试</div><div class="rail-step">独立 OQC</div><div class="rail-step">实景机房压测</div><div class="rail-step">包装发货</div></div>', '<span class="panel-head-meta">数据更新时间 09:46</span>')+
      `<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>现场待办工单</h2><p>优先处理即将超时与等待检验的设备</p></div><a class="link-button" href="#/front/production">查看全部 →</a></div><div class="panel-body">${state.workorders.slice(0,4).map(workRow).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>运营提醒</h2><p>需要负责人关注的异常</p></div><span class="panel-head-meta">3 项</span></div><div class="panel-body"><div class="alert-item"><span class="alert-symbol">!</span><span class="alert-copy"><b>800G 网卡低于安全库存</b><small>备件区 E-01-01 · 建议补货 5 张</small></span><span class="alert-count">紧急</span></div><div class="alert-item"><span class="alert-symbol">◷</span><span class="alert-copy"><b>1 台设备待出厂检验</b><small>WO-260925-016 · 已等待 46 分钟</small></span><span class="alert-count">待办</span></div><div class="alert-item"><span class="alert-symbol">↧</span><span class="alert-copy"><b>采购单分批到货</b><small>DEMO-PO-25031 · 仍有 3 件未收</small></span><span class="alert-count">跟进</span></div></div></section></div>`+
      `<div class="two-col"><section class="panel"><div class="panel-head"><h2>工序在制数量</h2><span class="panel-head-meta">授权范围内 · 示例</span></div><div class="panel-body"><div class="bar-list">${[['收货 / IQC',62,8],['维修中',83,11],['测试 / OQC',38,5],['等待备件',24,3]].map(([name,width,count])=>`<div class="bar-item"><span class="bar-label">${name}</span><span class="bar-track"><span class="bar-fill" style="display:block;width:${width}%"></span></span><b class="bar-value">${count}</b></div>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><h2>快捷入口</h2><span class="panel-head-meta">按岗位授权展示</span></div><div class="panel-body"><div class="toolbar-row"><a class="btn" href="#/qr/scan">⌗ 扫码追溯</a><a class="btn" href="#/data/inventory">▤ 库存中心</a><a class="btn" href="#/admin/people">♙ 员工管理</a></div><p class="panel-head-meta" style="margin-top:14px">个人手机与工位扫码枪在二维码追溯板块管理。</p></div></section></div>`;
  }
  function production(){
    let list=state.workorders.filter(item=>(!state.query||[item.id,item.customer,item.sn,item.fault,item.owner].join(' ').toLowerCase().includes(state.query.toLowerCase()))&&(state.status==='全部状态'||!state.status||item.status===state.status));
    const rows=list.map(item=>`<tr data-work="${esc(item.id)}"><td><span class="cell-primary">${esc(item.id)}</span><div class="cell-secondary">${esc(item.updated)} 更新</div></td><td><span class="cell-primary">${esc(item.customer)}</span><div class="cell-secondary">${esc(item.sn)}</div></td><td><span class="cell-primary">${esc(item.model)}</span><div class="cell-secondary">${esc(item.fault)}</div></td><td>${pill(item.status)}</td><td>${item.priority==='加急'?'<span class="priority-high">● 加急</span>':'<span class="priority-normal">普通</span>'}</td><td>${esc(item.owner)}</td><td><button class="link-button" data-work="${esc(item.id)}">查看 ›</button></td></tr>`).join('');
    return head('生产工作台','工序队列、负责人和时效集中呈现，现场员工从这里处理每日维修任务。',btn('＋ 登记收货','new-work',true))+
      `<div class="kpi-grid">${kpi('待入场检测','03','最早等待 26 分钟','◉')}${kpi('维修执行中','11','含 2 台待料','⚒')}${kpi('待测试 / OQC','05','需质量人员复核','✓')}${kpi('今日计划交付','08','已完成 3 台','⇧')}</div>`+
      panel('当前工序路径','<div class="steps"><div class="step done">收货拆包</div><div class="step current">入场检测 / IQC</div><div class="step">故障诊断</div><div class="step">报价确认</div><div class="step">维修 / 组装</div><div class="step">维修测试</div><div class="step">独立 OQC</div><div class="step">实景机房压测</div><div class="step">包装发货</div></div>')+
      `<div class="toolbar"><div class="filter-row"><form data-form="work-filter" class="filter-row">${field('query','搜索工单 / SN / 客户…',state.query)}${select('status',statuses,state.status||'全部状态')}<button class="btn" type="submit">筛选</button></form></div><span class="panel-head-meta">${list.length} 条工单 · 原型数据</span></div>`+
      table(['工单编号','客户 / 设备SN','型号 / 故障摘要','当前工序','优先级','负责人','详情'],rows,'当前筛选没有工单')+
      `<div class="notice" style="margin-top:13px">工序流转和检测报告提交仅在本原型内演示，不会写入真实工单。</div>`;
  }
  function assetPage(){
    const list=state.assets.filter(item=>!state.query||[item.sn,item.customer,item.model,item.location].join(' ').toLowerCase().includes(state.query.toLowerCase()));
    return head('客户资产','客户送修设备独立建档，与维修中心自有备件分账管理。',btn('＋ 登记送修资产','new-asset',true))+
      `<div class="toolbar"><form data-form="asset-filter" class="filter-row">${field('query','搜索客户 / SN / 型号…',state.query)}${select('status',['全部状态','待送修','维修中','待交付'],state.status||'全部状态')}<button class="btn" type="submit">筛选</button></form><span class="panel-head-meta">${list.length} 台示例设备</span></div>`+
      table(['设备序列号','客户','服务器型号','当前区域','服务属性','收货时间','标签'],list.map(item=>`<tr data-asset="${esc(item.sn)}"><td><span class="cell-primary">${esc(item.sn)}</span></td><td>${esc(item.customer)}</td><td>${esc(item.model)}</td><td>${esc(item.location)}</td><td>${pill(item.warranty)}</td><td>${esc(item.received)}</td><td><button class="link-button" data-label="${esc(item.sn)}">标签预览</button></td></tr>`).join(''));
  }
  function inventoryPage(){
    const parts=state.view.split('/');const category=parts[2],sub=parts[3];
    if(!category){
      return head('库存中心','先按主类和细分类定位物料，再进入最终清单；库存量为虚拟展示。',btn('＋ 新增物料','fake-save',true))+
        `<div class="kpi-grid">${kpi('物料品类','27','九大类演示档案','▤')}${kpi('账面库存','286','按SKU数量汇总','▦')}${kpi('安全库存预警','03','需采购评估','!')}${kpi('今日库存流水','18','入库 / 领料 / 退料','↕')}</div>`+
        panel('选择物料主类',`<div class="category-grid">${state.categories.map(cat=>`<a class="category-tile" href="#/data/inventory/${cat.code}"><span class="category-count">${state.inventory.filter(row=>row.category===cat.code).length} 项</span><span class="category-icon">${cat.icon}</span><b>${esc(cat.name)}</b><small>3 个细分类 · 点击展开</small></a>`).join('')}</div>`,'九宫格分类')+
        `<div class="toolbar-row"><a class="btn" href="#/qr/scan">⌗ 扫码登记入库</a><a class="btn" href="#/data/purchasing">进入采购收货 →</a></div>`;
    }
    const cat=state.categories.find(item=>item.code===category);
    if(!cat)return head('未找到分类','请从库存主类重新选择。',`<a class="btn" href="#/data/inventory">返回库存中心</a>`);
    if(!sub){
      return `<div class="crumbs"><a href="#/data/inventory">库存中心</a><span>/</span><b>${esc(cat.name)}</b></div>`+head(cat.name,'选择细分类，查看对应物料清单。')+
        `<div class="category-grid">${cat.subs.map(item=>`<a class="category-tile" href="#/data/inventory/${cat.code}/${item.code}"><span class="category-count">${state.inventory.filter(row=>row.category===cat.code&&row.sub===item.code).length} 项</span><span class="category-icon">↳</span><b>${esc(item.name)}</b><small>打开物料清单 →</small></a>`).join('')}</div>`;
    }
    const subName=cat.subs.find(item=>item.code===sub)?.name||'待确认分类';
    const items=state.inventory.filter(item=>item.category===category&&item.sub===sub&&(!state.query||[item.sku,item.name,item.bin].join(' ').toLowerCase().includes(state.query.toLowerCase())));
    const rows=items.map(item=>`<tr><td><div class="sku-name">${miniQr()}<span><span class="qr-code">${esc(item.sku)}</span><div class="cell-secondary">二维码可查档案</div></span></div></td><td><span class="cell-primary">${esc(item.name)}</span><div class="cell-secondary">${esc(cat.name)} / ${esc(subName)}</div></td><td><span class="cell-primary ${item.health==='偏低'?'qty-low':''}">${item.qty} ${esc(item.unit)}</span><div class="cell-secondary">已预留 ${item.reserved}</div></td><td>${esc(item.bin)}</td><td>${pill(item.health)}</td><td><button class="link-button" data-label="${esc(item.sku)}">标签预览</button></td></tr>`).join('');
    return `<div class="crumbs"><a href="#/data/inventory">库存中心</a><span>/</span><a href="#/data/inventory/${cat.code}">${esc(cat.name)}</a><span>/</span><b>${esc(subName)}</b></div>`+
      head(subName,'物料最终清单 · 账面库存演示数据。',btn('扫码登记入库','qr-prefill',true))+
      `<div class="toolbar"><form data-form="inventory-filter" class="filter-row">${field('query','搜索物料编码 / 名称 / 库位…',state.query)}<button class="btn" type="submit">查询</button><button class="btn btn-quiet" type="button" data-action="clear-filter">清除</button></form><span class="panel-head-meta">${items.length} 个SKU</span></div>`+
      table(['物料编码 / 二维码','物料名称','可用库存','仓储库位','安全状态','操作'],rows,'该细分类暂无物料')+
      `<div class="notice" style="margin-top:13px">扫码只帮助识别物料与来源单据；库存数量需经收货核验或领料业务确认后变更。</div>`;
  }
  function purchasing(){const rows=state.purchases.filter(item=>!state.query||[item.id,item.supplier,item.item,item.status].join(' ').toLowerCase().includes(state.query.toLowerCase())).map(item=>`<tr><td><span class="cell-primary">${esc(item.id)}</span><div class="cell-secondary">${esc(item.date)} 创建</div></td><td>${esc(item.supplier)}</td><td>${esc(item.item)}</td><td><span class="cell-primary">${item.received} / ${item.ordered}</span><div class="cell-secondary">已收 / 订购</div></td><td>${pill(item.status)}</td><td><button class="link-button" data-action="fake-receive" data-id="${esc(item.id)}">收货详情</button>　<button class="link-button" data-label="${esc(item.id)}">二维码</button></td></tr>`).join('');return head('采购管理','采购申请、审批状态、分批到货和收货流水。',btn('＋ 新建采购申请','fake-save',true))+`<div class="kpi-grid">${kpi('待审批','02','等待负责人确认','◷')}${kpi('在途订单','03','含分批到货','↧')}${kpi('本月采购额','¥ 86.4万','虚拟汇总金额','￥')}${kpi('待验收批次','04','需仓库人员核验','✓')}</div><div class="toolbar"><form data-form="purchase-filter" class="filter-row">${field('query','搜索采购单 / 供应商 / 物料…',state.query)}${select('status',['全部状态','待审批','分批到货','已收齐'],state.status||'全部状态')}<button class="btn" type="submit">筛选</button></form><span class="panel-head-meta">${state.purchases.length} 条采购单</span></div>`+table(['采购单号','供应商','物料','到货进度','状态','操作'],rows)}
  function commercial(){
    const quoteRows=[
      ['DEMO-QT-018','WO-260925-018','示例客户·智算中心',money(1840000),'已确认'],
      ['DEMO-QT-017','WO-260925-017','示例客户·云图科技',money(2130000),'已确认'],
      ['DEMO-QT-016','WO-260925-016','示例客户·北辰实验室',money(1486000),'已确认'],
      ['DEMO-QT-015','WO-260925-015','示例客户·星河智算',money(1290000),'已确认'],
      ['DEMO-QT-014','WO-260925-014','示例客户·算力云',money(825000),'已确认'],
      ['DEMO-QT-013','WO-260925-013','示例客户·研究院',money(18600),'草稿']
    ];
    const contractRows=state.contracts.map(item=>[item.id,item.customer,item.quote,money(item.amount),item.status]);
    const rows=items=>items.map(row=>`<tr>${row.map((value,index)=>`<td>${index===row.length-1?pill(value):esc(value)}</td>`).join('')}<td><button class="link-button" data-action="fake-save">详情</button></td></tr>`).join('');
    return head('报价与合同','报价版本、客户确认和合同归档集中查看；已签合同金额将汇入财务看板。',btn('＋ 新建报价版本','fake-save',true))+`<div class="two-col"><section class="panel"><div class="panel-head"><h2>报价台账</h2><span class="panel-head-meta">${quoteRows.length} 个示例版本</span></div>${table(['报价 / 关联工单','客户','报价总额','状态',''],rows(quoteRows))}</section><section class="panel"><div class="panel-head"><h2>合同台账</h2><span class="panel-head-meta">${state.contracts.length} 份已签示例合同</span></div>${table(['合同号','客户','关联报价','合同金额','状态',''],rows(contractRows))}</section></div><div class="notice">报价与合同金额为虚拟演示数据；正式系统应以签署状态和合同版本为财务汇总口径。</div>`;
  }
  function financePage(){
    const signed=state.contracts.filter(item=>item.status==='已签署');
    const signedTotal=signed.reduce((sum,item)=>sum+item.amount,0);
    const revenue=signed.reduce((sum,item)=>sum+item.revenue,0);
    const received=signed.reduce((sum,item)=>sum+item.received,0);
    const receivable=signed.reduce((sum,item)=>sum+Math.max(0,item.revenue-item.received),0);
    const expenses=state.financeCosts.filter(item=>item.type==='expense');
    const expenseTotal=expenses.reduce((sum,item)=>sum+item.amount,0);
    const purchase=state.financeCosts.find(item=>item.type==='procurement')?.amount||0;
    const inventoryValue=state.financeCosts.find(item=>item.type==='inventory')?.amount||0;
    const contractRows=signed.map(item=>`<tr><td><span class="cell-primary">${esc(item.id)}</span><div class="cell-secondary">${esc(item.signed)} 签署 · ${esc(item.quote)}</div></td><td>${esc(item.customer)}</td><td>${money(item.amount)}</td><td>${money(item.revenue)}</td><td>${money(item.received)}</td><td><span class="cell-primary ${item.revenue>item.received?'qty-low':''}">${money(Math.max(0,item.revenue-item.received))}</span></td><td>${pill(item.status)}</td></tr>`).join('');
    const maxExpense=Math.max(...expenses.map(item=>item.amount),1);
    const expenseRows=expenses.map(item=>`<div class="finance-cost-row"><span>${esc(item.category)}<small>${esc(item.note)}</small></span><span class="finance-cost-track"><i style="width:${Math.round(item.amount/maxExpense*100)}%"></i></span><b>${money(item.amount)}</b></div>`).join('');
    return head('财务看板','合同签约、收入回款、应收账款与运营费用汇总。当前全为虚拟演示数，不代表公司实际财务数据。',`<span class="pill pill-cyan">2026年9月 · 演示账期</span>`)+
      `<div class="kpi-grid">${kpi('已签合同金额',money(signedTotal),`${signed.length} 份已签合同`,'▧')}${kpi('已确认营收',money(revenue),'按演示合同收入确认额','￥')}${kpi('已回款',money(received),'来自合同回款台账','↙')}${kpi('应收账款',money(receivable),'已确认收入减已回款','◷')}</div>`+
      `<div class="finance-quick"><span><small>本月运营费用</small><b>${money(expenseTotal)}</b></span><span><small>物料采购金额</small><b>${money(purchase)}</b></span><span><small>备件库存账面值</small><b>${money(inventoryValue)}</b></span><span><small>应收占已确认收入</small><b>${revenue?Math.round(receivable/revenue*100):0}%</b></span></div>`+
      `<div class="two-col finance-panels"><section class="panel"><div class="panel-head"><div><h2>签约与回款</h2><p>财务汇总直接读取同一组合同示例</p></div><a class="link-button" href="#/data/commercial">报价与合同 →</a></div><div class="panel-body"><div class="finance-progress"><div class="finance-progress-label"><span>已确认营收</span><b>${money(revenue)}</b></div><div class="finance-track"><i style="width:${revenue?Math.round(received/revenue*100):0}%"></i></div><div class="finance-progress-caption"><span>已回款 ${money(received)}</span><span>应收 ${money(receivable)}</span></div></div><div class="finance-facts"><span><small>合同单数</small><b>${signed.length} 单</b></span><span><small>合同总额</small><b>${money(signedTotal)}</b></span><span><small>已确认收入</small><b>${money(revenue)}</b></span><span><small>未开票合同额</small><b>${money(signed.reduce((sum,item)=>sum+Math.max(0,item.amount-item.revenue),0))}</b></span></div></div></section><section class="panel"><div class="panel-head"><div><h2>运营费用与薪酬福利</h2><p>月度汇总 · 不展示个人薪酬明细</p></div><span class="panel-head-meta">费用合计 ${money(expenseTotal)}</span></div><div class="panel-body finance-cost-list">${expenseRows}<div class="toolbar-row" style="margin-top:10px"><a class="btn btn-sm" href="#/admin/people">员工与组织</a><span class="panel-head-meta">工资与社保福利按部门授权查看</span></div></div></section></div>`+
      `<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>合同应收明细</h2><p>应收按已确认收入减回款计算，不含未开票合同额</p></div><span class="panel-head-meta">${signed.length} 份演示合同</span></div>${table(['合同 / 签署时间','客户','合同金额','确认营收','已回款','应收账款','状态'],contractRows)}</section><section class="panel"><div class="panel-head"><div><h2>物料采购与库存资产</h2><p>采购现金支出与库存资产分开观察</p></div><a class="link-button" href="#/data/purchasing">采购台账 →</a></div><div class="panel-body"><div class="finance-inventory"><div><small>本月物料采购</small><b>${money(purchase)}</b><span>按采购订单金额汇总</span></div><div><small>备件库存账面价值</small><b>${money(inventoryValue)}</b><span>按期末库存估值</span></div></div><div class="notice" style="margin-top:12px">采购额不直接等同当期费用；零件入库形成库存，领用/耗用后再按正式会计规则结转成本。</div><div class="toolbar-row" style="margin-top:11px"><a class="btn btn-sm" href="#/data/inventory">查看物料库存</a><a class="btn btn-sm" href="#/data/purchasing">查看采购收货</a></div></div></section></div>`;
  }
  function peoplePage(){return head('组织与员工','部门、员工与工作账号的关系总览。离职与调岗在正式系统中应联动账号状态。',btn('＋ 新增员工','fake-save',true))+`<div class="kpi-grid">${kpi('在职员工','24','含 6 个示例账号','♙')}${kpi('维修工程师','08','硬件 / 液冷 / BGA','⚒')}${kpi('质量与测试','06','来料 / 测试 / OQC','✓')}${kpi('待首次登录','02','需修改初始密码','◉')}</div><div class="toolbar"><form data-form="people-filter" class="filter-row">${field('query','搜索姓名 / 部门 / 岗位…',state.query)}${select('status',['全部状态','在岗','外出'],state.status||'全部状态')}<button class="btn" type="submit">筛选</button></form><span class="panel-head-meta">组织层级：玹擎科技 / 深圳维修中心</span></div>`+table(['员工','部门','工作角色','状态','数据范围','操作'],state.people.filter(person=>(!state.query||[person.name,person.department,person.role].join(' ').includes(state.query))&&(!state.status||state.status==='全部状态'||person.state===state.status)).map(person=>`<tr><td><span class="cell-primary">${esc(person.name)}</span><div class="cell-secondary">示例员工 · 维修中心</div></td><td>${esc(person.department)}</td><td>${esc(person.role)}</td><td>${pill(person.state)}</td><td>${person.role==='维修工程师'?'本人负责工单':'所属部门'}</td><td><button class="link-button" data-action="fake-save">编辑 / 调岗</button></td></tr>`).join(''))}
  function rolesPage(){const perms=['工单查看','工单创建','维修执行','来料检验','维修测试','出厂放行','库存查看','库存写入','二维码扫描','人员管理'];const matrix=state.roles.map(role=>`<tr><td><span class="cell-primary">${esc(role.name)}</span><div class="cell-secondary">${role.members} 名员工 · ${esc(role.scope)}</div></td>${perms.map((_,index)=>`<td class="${index<(role.name==='经营负责人'?9:role.name==='维修工程师'?5:role.name==='仓库管理员'?8:7)?'check':'cross'}">${index<(role.name==='经营负责人'?9:role.name==='维修工程师'?5:role.name==='仓库管理员'?8:7)?'✓':'—'}</td>`).join('')}<td><button class="link-button" data-action="fake-save">调整权限</button></td></tr>`).join('');return head('角色与权限','按岗位配置功能权限与数据范围。矩阵仅为演示，不会改变真实账号。',btn('＋ 新建角色','fake-save',true))+`<div class="notice notice-warn" style="margin-bottom:13px">高风险权限：账号管理、采购审批、OQC 放行建议配置职责分离，并保留操作审计。</div><section class="panel"><div class="panel-head"><div><h2>岗位权限矩阵</h2><p>✓ 已授权　— 未授权</p></div><span class="panel-head-meta">${state.roles.length} 个参考角色</span></div><div class="panel-body matrix-wrap"><table class="permission-matrix"><thead><tr><th>角色 / 范围</th>${perms.map(item=>`<th>${item}</th>`).join('')}<th>维护</th></tr></thead><tbody>${matrix}</tbody></table></div></section>`}
  function auditPage(){return head('操作审计','按时间、操作人、对象与结果检索关键业务事件。')+`<div class="toolbar"><form data-form="audit-filter" class="filter-row">${field('query','搜索操作人 / 对象 / 动作…',state.query)}${select('status',['全部状态','成功','待复核'],state.status||'全部状态')}<button class="btn" type="submit">筛选</button></form><span class="panel-head-meta">最近 24 小时 · 示例日志</span></div>`+table(['发生时间','操作人','动作','业务对象','结果','关联二维码'],state.audit.filter(row=>!state.query||[row.user,row.action,row.target,row.result].join(' ').toLowerCase().includes(state.query.toLowerCase())).map(row=>`<tr><td>${esc(row.time)}</td><td>${esc(row.user)}</td><td>${esc(row.action)}</td><td><span class="qr-code">${esc(row.target)}</span></td><td>${pill('成功')}</td><td><button class="link-button" data-label="${esc(row.target)}">查看追溯</button></td></tr>`).join(''))}
  function qrScan(){const options=['查询','来料','入库','维修','检测','出厂'];return head('扫码工作台','二维码追溯独立入口。手机扫码或固定扫码枪录入后，先核验对象，再进入授权业务操作。')+`<div class="scan-layout"><section class="panel"><div class="panel-head"><div><h2>扫码核验</h2><p>键盘模拟扫码枪：光标进入输入框后扫码内容自动录入</p></div><span class="pill pill-green">扫码服务 · 演示</span></div><div class="panel-body"><form data-form="scan" class="scan-stage"><div class="eyebrow">QR TRACE DESK</div><div class="scan-target"><span class="scan-corners"></span><span class="scan-beam"></span><b>⌗</b></div><h3>将光标放在输入框，扫描业务标签</h3><p>扫码编号只用于定位对象。入库、出库或工序放行仍须由有权限的员工确认对应业务表单。</p><div class="scan-input"><input name="code" placeholder="扫描或输入 XA-DEMO…" autocomplete="off" required>${select('use',options,'查询')}<button class="btn btn-primary" type="submit">核验</button></div><div class="sample-codes">${state.qrLabels.slice(0,4).map(label=>`<button class="sample-code" type="button" data-scan-sample="${esc(label.code)}">${esc(label.kind)} · ${esc(label.code.slice(-8))}</button>`).join('')}</div></form></div></section><section class="panel"><div class="panel-head"><h2>对象解析结果</h2><span class="panel-head-meta">需登录后查看 · 原型模拟</span></div><div class="panel-body">${state.qrResult?qrResult(state.qrResult):`<div class="scan-stage" style="min-height:220px"><span class="category-icon" style="height:42px;width:42px;font-size:22px">⌗</span><h3>等待扫码</h3><p>选择一个示例标签或输入编号，查看对应资产、备件或报告摘要。</p></div>`}</div></section></div><section class="panel"><div class="panel-head"><h2>常用追溯入口</h2><a class="link-button" href="#/qr/history">查看最近记录 →</a></div><div class="panel-body"><div class="toolbar-row"><a class="btn" href="#/qr/devices">绑定手机 / 扫码枪</a><a class="btn" href="#/qr/labels">标签与标签类型</a><a class="btn" href="#/data/inventory">进入备件清单</a></div></div></section>`}
  function qrResult(event){const label=state.qrLabels.find(item=>item.code.toLowerCase()===event.code.toLowerCase());if(!label)return `<div class="notice notice-warn">没有匹配的示例二维码。请使用标有 DEMO 的样例编号。</div>`;let facts=[['对象类型',label.kind],['业务编号',label.code],['对象摘要',label.name],['扫码用途',event.use],['核验结果','匹配 · 已记录演示事件']];const work=state.workorders.find(item=>item.sn===label.code||item.id===label.code||`XA-DEMO-${item.id}`===label.code);if(work)facts.push(['当前工序',work.status],['维修负责人',work.owner]);const part=state.inventory.find(item=>item.sku===label.code);if(part)facts.push(['可用库存',`${part.qty-part.reserved} ${part.unit}`],['库位',part.bin]);return `<div class="result-box"><div class="result-heading"><b>${esc(label.name)}</b><span class="pill pill-green">核验成功</span></div><div class="result-facts">${facts.map(([name,value])=>`<div class="result-fact"><small>${esc(name)}</small><b>${esc(value)}</b></div>`).join('')}</div><div class="notice" style="margin-top:11px">这条扫码已写入本页临时演示记录。生产环境应由登录账号、设备绑定状态与具体业务权限共同决定可见内容。</div></div>`}
  function devicesPage(){return head('设备绑定','独立管理员工手机和固定扫码设备，绑定关系仅在当前页面内演示。',btn('＋ 绑定新设备','binding-modal',true))+`<div class="notice notice-warn" style="margin-bottom:14px">配对码与设备状态为虚拟示例。此页面不申请摄像头权限、不连接手机或蓝牙扫码枪。</div><div class="device-grid">${state.devices.map(device=>`<article class="device-card"><div class="device-top"><span class="device-symbol">${device.kind==='员工手机'?'▣':'⌗'}</span><span class="device-title"><b>${esc(device.kind)} · ${esc(device.id)}</b><small>${esc(device.owner)}</small></span>${pill(device.state)}</div><div class="device-body"><span class="device-fact"><small>绑定人员 / 区域</small><b>${esc(device.owner)} · ${esc(device.area)}</b></span><span class="device-fact"><small>连接状态</small><b class="connection">${esc(device.connection)}</b></span><span class="device-fact"><small>最近扫码</small><b>${esc(device.last)}</b></span><span class="device-fact"><small>绑定策略</small><b>${device.kind==='员工手机'?'员工账号':'工位 / 库区'}</b></span></div><div class="toolbar-row">${device.state==='已绑定'?`<button class="btn btn-danger btn-sm" data-unbind="${esc(device.id)}">解绑演示设备</button>`:`<button class="btn btn-primary btn-sm" data-bind-existing="${esc(device.id)}">开始绑定</button>`}<button class="btn btn-sm" data-action="toggle-connection" data-id="${esc(device.id)}">切换在线状态</button></div></article>`).join('')}</div>`+panel('新增设备配对',`<form data-form="bind-device" class="binding-form">${select('kind',['员工手机','固定扫码枪'])}${field('deviceId','设备编号（DEMO-…）')}<select class="field" name="owner"><option>选择员工</option>${state.people.map(person=>`<option>${esc(person.name)}</option>`).join('')}</select><select class="field" name="area"><option>选择工位 / 区域</option>${['来料检测区','备件仓库','硬件维修区','BGA 维修间','液冷测试区','OQC 检验区','成品交付区'].map(area=>`<option>${area}</option>`).join('')}</select><button class="btn btn-primary" type="submit">生成演示配对关系</button></form>`,'手机与扫码枪分开授权')}
  function labelsPage(){const type=state.status||'全部类型',items=state.qrLabels.filter(label=>(type==='全部类型'||label.kind===type)&&(!state.query||[label.code,label.kind,label.name].join(' ').toLowerCase().includes(state.query.toLowerCase())));return head('标签管理','按资产、工单、物料、采购单和报告管理二维码标签。图案只作排版预览，不可用于真实扫码。',btn('＋ 标签打印任务','fake-save',true))+`<div class="toolbar"><form data-form="label-filter" class="filter-row">${field('query','搜索标签编号 / 对象…',state.query)}${select('status',['全部类型',...new Set(state.qrLabels.map(item=>item.kind))],type)}<button class="btn" type="submit">筛选</button></form><span class="panel-head-meta">${items.length} 个示例标签</span></div><div class="data-grid">${items.map(label=>`<div class="qr-label-card">${miniQr()}<span><b>${esc(label.name)}</b><small>${esc(label.kind)} · <span class="qr-code">${esc(label.code)}</span></small></span><button class="btn btn-sm" data-label="${esc(label.code)}">预览</button></div>`).join('')}</div><div class="notice notice-warn" style="margin-top:13px">生产标签需由真实二维码编码器生成，并按标签模板、尺寸与打印机实测校验。</div>`}
  function historyPage(){const use=state.status||'全部用途';const events=state.qrEvents.filter(event=>(use==='全部用途'||event.use===use)&&(!state.query||[event.user,event.code,event.use,event.result].join(' ').toLowerCase().includes(state.query.toLowerCase())));return head('扫码记录','可按人员、用途和业务编号追溯近期扫码交接。')+`<div class="toolbar"><form data-form="history-filter" class="filter-row">${field('query','搜索操作人 / 编号 / 用途…',state.query)}${select('status',['全部用途',...new Set(state.qrEvents.map(event=>event.use))],use)}<button class="btn" type="submit">筛选</button></form><span class="panel-head-meta">${events.length} 条本地演示记录</span></div>`+panel('最近扫码事件',events.length?`<div class="scan-history">${events.map(event=>`<div class="history-row"><span>${esc(event.time)}</span><b>${esc(event.user)}</b><span class="qr-code">${esc(event.code)}</span><span>${esc(event.use)}</span>${pill(event.result)}</div>`).join('')}</div>`:'<div class="empty-state">当前筛选没有扫码记录</div>')}
  function openWork(id){const item=state.workorders.find(row=>row.id===id);if(!item)return;const drawer=$('#drawer');drawer.innerHTML=`<div class="drawer-head"><b>${esc(item.id)} · ${esc(item.status)}</b><button class="drawer-close" data-action="close-drawer">×</button></div><section class="drawer-section"><h3>${esc(item.model)} · ${esc(item.customer)}</h3><p>设备 SN：${esc(item.sn)}</p><p>区域：${esc(item.zone)}　负责人：${esc(item.owner)}</p><p>故障：${esc(item.fault)}</p><p>优先级：${esc(item.priority)}　最近更新：${esc(item.updated)}</p></section><section class="drawer-section"><h3>维修流程时间线</h3><div class="steps"><div class="step done">收货</div><div class="step done">IQC</div><div class="step current">维修</div><div class="step">维修测试</div><div class="step">独立 OQC</div><div class="step">实景机房压测</div><div class="step">包装发货</div></div><p>机房压测记录机柜、负载、温度、功耗、运行时长与异常；通过后进入防静电与抗震包装、出库交接。</p></section><section class="drawer-section"><h3>报告与凭证</h3><div class="report-card"><div class="report-card-head"><b>入场检测报告</b>${pill('已归档')}</div><p>软件：Burn-in Suite · DEMO 版。GPU、内存、PCIe 与网络检查为示例引用。</p></div><div class="report-card"><div class="report-card-head"><b>维修测试报告</b>${pill(item.status==='完成 OQC'?'已归档':'待提交')}</div><p>测试项目与结论展示为虚拟记录，二维码预览不具备扫码功能。</p></div><div class="report-card"><div class="report-card-head"><b>机房压测与发货交接</b>${pill('待执行')}</div><p>压测报告、包装照片、封箱编号与承运交接凭证应分别归档并关联设备二维码。</p></div><div class="qr-preview">${miniQr()}<span><b>${esc(item.sn)}</b><small>装饰性二维码布局预览</small></span></div></section><div class="drawer-actions"><button class="btn btn-primary" data-action="fake-save">模拟分派 / 流转</button><button class="btn" data-label="${esc(item.sn)}">标签预览</button></div><div class="notice notice-warn">此侧栏只用于比较工单页面信息结构，不会创建、派发或变更真实维修工单。</div>`;drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');$('#drawerBackdrop').hidden=false}
  function openLabel(code){const label=state.qrLabels.find(item=>item.code===code)||{code,name:code,kind:'示例对象'};const drawer=$('#drawer');drawer.innerHTML=`<div class="drawer-head"><b>二维码标签预览</b><button class="drawer-close" data-action="close-drawer">×</button></div><section class="drawer-section"><div class="qr-preview"><span class="qr-pattern">${Array.from({length:81},()=>'<i></i>').join('')}</span><span><b>${esc(label.name)}</b><small>${esc(label.kind)} · ${esc(label.code)}</small></span></div><p>此图仅用于页面排版参考，不是可扫描的生产二维码。</p></section><div class="drawer-actions"><button class="btn btn-primary" data-action="print-preview">打开打印预览</button><button class="btn" data-action="close-drawer">关闭</button></div>`;drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');$('#drawerBackdrop').hidden=false}
  function closeDrawer(){$('#drawer').classList.remove('open');$('#drawer').setAttribute('aria-hidden','true');$('#drawerBackdrop').hidden=true}
  function scan(code,use){const label=state.qrLabels.find(item=>item.code.toLowerCase()===code.trim().toLowerCase());const event={time:new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date()),user:'演示账号',code:code.trim(),use,result:label?'已核验':'未匹配'};state.qrEvents.unshift(event);state.qrResult=event;render();if(label)showToast('演示扫码核验成功');else showToast('未找到该示例编号')}
  function render(){renderNav();const title=titles[state.view]||'物料清单';$('#pageHeading').textContent=title;let html='';if(state.view==='front/overview')html=overview();else if(state.view==='front/production')html=production();else if(state.view==='data/assets')html=assetPage();else if(state.view==='data/inventory'||state.view.startsWith('data/inventory/'))html=inventoryPage();else if(state.view==='data/purchasing')html=purchasing();else if(state.view==='data/commercial')html=commercial();else if(state.view==='data/finance')html=financePage();else if(state.view==='admin/people')html=peoplePage();else if(state.view==='admin/roles')html=rolesPage();else if(state.view==='admin/audit')html=auditPage();else if(state.view==='qr/scan')html=qrScan();else if(state.view==='qr/devices')html=devicesPage();else if(state.view==='qr/labels')html=labelsPage();else if(state.view==='qr/history')html=historyPage();$('#view').innerHTML=html}
  function submitFilter(form){const values=Object.fromEntries(new FormData(form));state.query=values.query||'';state.status=values.status||'';render()}
  document.addEventListener('click',event=>{
    const target=event.target.closest('[data-work],[data-label],[data-scan-sample],[data-action],[data-unbind],[data-bind-existing],[data-map-site],[data-map-view]');if(!target)return;
    if(target.dataset.work){event.preventDefault();openWork(target.dataset.work);return}
    if(target.dataset.label){event.preventDefault();openLabel(target.dataset.label);return}
    if(target.dataset.scanSample){const code=target.dataset.scanSample;const input=$('#view [name="code"]');if(input)input.value=code;scan(code,'查询');return}
    if(target.dataset.mapSite){state.selectedSite=target.dataset.mapSite;render();return}
    if(target.dataset.mapView){state.mapView=target.dataset.mapView;render();return}
    if(target.dataset.unbind){const device=state.devices.find(item=>item.id===target.dataset.unbind);if(device){device.state='待绑定';device.owner=device.kind==='员工手机'?'待员工配对':'待指定工位';device.area='未绑定';showToast('演示设备已解绑')}render();return}
    if(target.dataset.bindExisting){const device=state.devices.find(item=>item.id===target.dataset.bindExisting);if(device){device.state='已绑定';device.owner=device.kind==='员工手机'?'陈工':'备件库位终端 02';device.area=device.kind==='员工手机'?'个人绑定':'备件仓库';device.connection='在线';showToast('演示绑定已更新')}render();return}
    const action=target.dataset.action;if(action==='close-drawer'){closeDrawer();return}if(action==='toggle-connection'){const device=state.devices.find(item=>item.id===target.dataset.id);if(device)device.connection=device.connection==='在线'?'离线':'在线';render();showToast('已切换演示连接状态');return}if(action==='fake-save'){showToast('演示操作完成，不保存真实业务数据');return}if(action==='new-work'||action==='new-asset'||action==='qr-prefill'||action==='binding-modal'){showToast('此页面为参考原型，未连接真实业务表单');return}if(action==='clear-filter'){state.query='';state.status='';render();return}if(action==='print-preview'){window.print();return}if(action==='notifications'){showToast('当前为演示通知中心');return}
  });
  document.addEventListener('change',event=>{if(event.target.name==='mapProduct'){state.mapProduct=event.target.value;render()}if(event.target.name==='mapYears'){state.mapYears=event.target.value;render()}});
  document.addEventListener('submit',event=>{
    const form=event.target;if(!form.dataset.form)return;event.preventDefault();
    if(['work-filter','asset-filter','purchase-filter','inventory-filter','people-filter','audit-filter','label-filter','history-filter'].includes(form.dataset.form)){submitFilter(form);return}
    if(form.dataset.form==='scan'){const values=Object.fromEntries(new FormData(form));scan(values.code,values.use);return}
    if(form.dataset.form==='bind-device'){const values=Object.fromEntries(new FormData(form));if(!values.deviceId||values.owner==='选择员工'||values.area==='选择工位 / 区域'){showToast('请填写设备编号并指定人员/区域');return}const kind=values.kind==='员工手机'?'员工手机':'固定扫码枪';state.devices.unshift({id:values.deviceId,kind,owner:kind==='员工手机'?values.owner:values.deviceId,area:kind==='员工手机'?'个人绑定':values.area,state:'已绑定',last:'尚未扫码',connection:'在线'});showToast(kind+'演示绑定成功');render();return}
  });
  $('#drawerBackdrop').addEventListener('click',closeDrawer);
  document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();$('#globalSearch').focus();return}const point=event.target.closest('[data-map-site]');if(point&&(event.key==='Enter'||event.key===' ')){event.preventDefault();point.click()}});
  $('#globalSearch').addEventListener('keydown',event=>{if(event.key==='Enter'&&event.currentTarget.value.trim()){state.query=event.currentTarget.value.trim();location.hash='#/front/production';if(state.view==='front/production')render()}});
  window.addEventListener('hashchange',route);
  window.setInterval(()=>{state.mapUpdated=new Date();if(state.view==='front/overview')render()},30000);
  route();
})();
